"use client";

import { loadFont } from "@remotion/google-fonts/FunnelDisplay";
import type React from "react";
import { useEffect, useMemo, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  Img,
  interpolate,
  staticFile,
} from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import {
  type ResolvedElement,
  type Timing,
  useTimeline,
} from "@/lib/remocn/timeline";
import {
  DEFAULT_QUESTION,
  DEFAULT_REFUSAL,
  DEFAULT_WHEN,
  type PeekShutElementId,
  peekShutTimeline,
  split,
} from "./timeline";

const funnel = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface PeekShutProps {
  question?: string;
  refusal?: string;
  when?: string;
  src?: string;
  focusY?: number;
  pan?: [number, number];
  zoom?: number;
  accent?: string;
  /** Text color of the question and refusal; overrides the theme ink. */
  ink?: string;
  background?: string;
  /** Typeface for the copy. Load it yourself; Funnel Display by default. */
  fontFamily?: string;
  /** Frames between words as a line rises in. */
  stagger?: number;
  /** Frame the slot snaps shut; the refusal follows it. */
  shutAt?: number;
  /** Size of the copy and slot, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  theme?: "dark" | "light";
  /**
   * Moves, trims or stretches the base line, the slot opening and shutting,
   * and single words of the question, refusal and "when" line, by the ids in
   * `./timeline`. Frames on the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<PeekShutElementId>;
}

const DEFAULT_PAN: [number, number] = [0.8, 0.57];

const THEMES = {
  dark: {
    bg: "#0B0B0F",
    ink: "#FFFFFF",
    line: "rgba(255,255,255,0.32)",
    accent: "#B79CFF",
  },
  light: {
    bg: "#FAFAFA",
    ink: "#121216",
    line: "rgba(18,18,22,0.3)",
    accent: "#6B4FD8",
  },
} as const;

const WGHT = 500;
const TRACK = -0.03;
const PITCH = 1.06;
const MEASURE_PX = 100;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_SNAP = Easing.bezier(0.7, 0, 0.9, 0.4);
const EASE_DRIFT = Easing.bezier(0.45, 0, 0.55, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const midway = (p: number) => p > 5e-4 && p < 1 - 5e-4;

let measureCtx: CanvasRenderingContext2D | null = null;

function em(s: string, family: string) {
  if (!measureCtx) {
    measureCtx = document.createElement("canvas").getContext("2d");
  }
  if (!measureCtx) throw new Error("peek-shut: no 2d context");
  measureCtx.font = `${WGHT} ${MEASURE_PX}px "${family}"`;
  return (
    measureCtx.measureText(s).width / MEASURE_PX + TRACK * Array.from(s).length
  );
}

function useFontsReady(family: string) {
  const [ready, setReady] = useState(false);
  const [handle] = useState(() => delayRender("peek-shut: fonts"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      funnel.waitUntilDone(),
      document.fonts.load(`${WGHT} 100px "${family}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (live) setReady(true);
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [handle, family]);
  return ready;
}

interface Row {
  words: { text: string; x: number }[];
  w: number;
}

function toRow(words: string[], family: string): Row {
  const space = em(" ", family);
  let x = 0;
  const out = words.map((text) => {
    const at = x;
    x += em(text, family) + space;
    return { text, x: at };
  });
  return { words: out, w: em(words.join(" "), family) };
}

function greedy(words: string[], maxEm: number, family: string): string[][] {
  const rows: string[][] = [];
  let cur: string[] = [];
  for (const w of words) {
    const next = [...cur, w];
    if (cur.length > 0 && em(next.join(" "), family) > maxEm) {
      rows.push(cur);
      cur = [w];
    } else {
      cur = next;
    }
  }
  if (cur.length) rows.push(cur);
  return rows;
}

function wrap(s: string, maxEm: number, family: string): Row[] {
  const words = split(s);
  let rows = greedy(words, maxEm, family);
  let m = maxEm;
  for (let guard = 0; guard < 30 && rows.length > 1; guard++) {
    m *= 0.96;
    const next = greedy(words, m, family);
    if (next.length > rows.length) break;
    rows = next;
  }
  return rows.map((row) => toRow(row, family));
}

function buildLayout(
  question: string,
  refusal: string,
  when: string,
  W: number,
  H: number,
  family: string,
) {
  const portrait = H > W * 1.1;
  const measure = W * (portrait ? 0.84 : 0.66);
  const hMax = portrait ? H * 0.05 : H * 0.1;
  let F = Math.min(W, H) * 0.1;
  let q: Row[] = [];
  let r: Row[] = [];
  let wn: Row[] = [];
  for (let guard = 0; guard < 16; guard++) {
    q = wrap(question, measure / F, family);
    r = wrap(refusal, measure / F, family);
    wn = wrap(when, measure / F, family);
    const room = H / 2 - hMax / 2 - F * 0.7 - H * (portrait ? 0.1 : 0.08);
    const tallest = Math.max(q.length, r.length + wn.length);
    if (((tallest - 1) * PITCH + 1.1) * F <= room) break;
    F *= 0.93;
  }
  return { q, r, wn, F, hMax, portrait };
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function PeekShut(props: PeekShutProps) {
  const {
    question = DEFAULT_QUESTION,
    refusal = DEFAULT_REFUSAL,
    when = DEFAULT_WHEN,
    src,
    focusY = 0.5,
    pan = DEFAULT_PAN,
    zoom = 3.2,
    accent,
    ink,
    background,
    fontFamily = funnel.fontFamily,
    scale = 1,
    delay = 0,
    speed = 1,
    theme = "dark",
    timing,
  } = props;
  const glide = useGlide();
  const frame = Math.max(0, useSceneFrame() - delay);
  const { width: W, height: H, durationInFrames } = useSceneConfig();
  // The clip after `delay`, in scene frames: the schedule compresses itself
  // to fit it, as before.
  const tl = useTimeline(
    peekShutTimeline,
    props,
    (durationInFrames - delay) * speed,
    timing,
  );
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const fg = ink ?? c.ink;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);
  const image = src ?? staticFile("hero.png");
  const ready = useFontsReady(fontFamily);

  const layout = useMemo(
    () =>
      ready ? buildLayout(question, refusal, when, W, H, fontFamily) : null,
    [ready, question, refusal, when, W, H, fontFamily],
  );

  if (!layout) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const { F, hMax, portrait } = layout;
  const t = frame * speed;

  const mx = W * (portrait ? 0.08 : 0.065);
  const cy = H / 2;
  const slotX = mx;
  const slotW = portrait ? W - 2 * mx : W * 0.56;
  const gap = F * 0.7;
  const hair = Math.max(1, Math.round(H / 720));

  const lineEl = tl.get("line");
  const openEl = tl.get("open");
  const shutEl = tl.get("shut");
  const drawn = interpolate(t, [lineEl.start, lineEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const opened = interpolate(t, [openEl.start, openEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const shut = interpolate(t, [shutEl.start, shutEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_SNAP,
  });
  const h = hMax * opened * (1 - shut);
  const drift = interpolate(t, [openEl.start, shutEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_DRIFT,
  });

  const IW = slotW * zoom;
  const IH = (IW * 9) / 16;
  const fx = pan[0] + (pan[1] - pan[0]) * drift;
  const ix = slotW / 2 - fx * IW;
  const iy = hMax / 2 - focusY * IH;
  const settle = 1 + 0.04 * (1 - opened);

  const rowH = F * 1.2;
  const lineTop = cy - hMax / 2 - gap - layout.q.length * PITCH * F;
  const belowTop = cy + hMax / 2 + gap * 0.9;
  // Layout rounds a box edge to whole pixels, so a slot edge eased by `top`
  // clicks open pixel by pixel; it sits where the open slot leaves it and
  // `dy` carries it there as a transform.
  const edge = (x: number, w: number, y: number, key: string, dy = 0) => (
    <div
      key={key}
      style={{
        position: "absolute",
        left: x,
        top: y - hair / 2,
        width: Math.max(0, w),
        height: hair,
        background: c.line,
        transform: Math.abs(dy) > 1e-3 ? `translateY(${dy}px)` : undefined,
      }}
    />
  );
  const reach = W * drawn;

  const block = (
    rows: Row[],
    top: number,
    el: (i: number) => ResolvedElement<PeekShutElementId>,
    color: string,
    key: string,
  ) => {
    let wi = 0;
    return rows.map((row, li) => (
      <div
        key={`${key}-${li}`}
        style={{
          position: "absolute",
          left: mx - F * 0.1,
          top: top + li * PITCH * F,
          width: row.w * F + F * 0.3,
          height: rowH,
          overflow: "hidden",
        }}
      >
        {row.words.map((w) => {
          const i = wi++;
          const wordEl = el(i);
          const q = interpolate(t, [wordEl.start, wordEl.end], [0, 1], {
            ...CLAMP,
            easing: EASE_OUT,
          });
          return (
            <div
              key={`${key}-w-${i}`}
              style={{
                position: "absolute",
                left: w.x * F + F * 0.1,
                top: 0,
                height: rowH,
                fontFamily,
                fontWeight: WGHT,
                fontSize: F,
                lineHeight: `${rowH}px`,
                letterSpacing: `${TRACK}em`,
                whiteSpace: "pre",
                color,
                transform: `translateY(${((1 - q) * rowH).toFixed(2)}px)${glide(midway(q))}`,
              }}
            >
              {w.text}
            </div>
          );
        })}
      </div>
    ));
  };

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <ScaleLayer scale={scale}>
        {block(layout.q, lineTop, (i) => tl.get(`question:${i}`), fg, "q")}
        {edge(0, reach, cy, "base")}
        <div
          style={{
            position: "absolute",
            left: slotX,
            top: cy - h / 2,
            width: slotW,
            height: h,
            overflow: "hidden",
          }}
        >
          <div
            style={{
              position: "absolute",
              left: 0,
              top: -(hMax - h) / 2,
              width: slotW,
              height: hMax,
            }}
          >
            <Img
              src={image}
              style={{
                position: "absolute",
                left: ix,
                top: iy,
                width: IW,
                height: IH,
                objectFit: "cover",
                transformOrigin: `${fx * 100}% ${focusY * 100}%`,
                transform: `scale(${settle.toFixed(4)})`,
              }}
            />
          </div>
        </div>
        {h > hair * 1.5
          ? [
              edge(
                slotX,
                Math.min(reach, slotX + slotW) - slotX,
                cy - hMax / 2,
                "e-t",
                (hMax - h) / 2,
              ),
              edge(
                slotX,
                Math.min(reach, slotX + slotW) - slotX,
                cy + hMax / 2,
                "e-b",
                (h - hMax) / 2,
              ),
            ]
          : null}
        {block(layout.r, belowTop, (i) => tl.get(`refusal:${i}`), fg, "r")}
        {block(
          layout.wn,
          belowTop + layout.r.length * PITCH * F,
          (i) => tl.get(`when:${i}`),
          hi,
          "wn",
        )}
      </ScaleLayer>
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The base line drawing across, the question rising word by word, the slot
// opening on the picture, snapping shut, then the refusal and the "when"
// line rising word by word. Frames on the 30 fps scene timeline, after
// `delay` and `speed`. When the schedule runs past the clip (less a hold) it
// is compressed to fit (`k`, down to 0.6). The ids are public: a saved
// `timing` prop refers to them.

export type PeekShutElementId =
  | "line"
  | `question:${number}`
  | "open"
  | "shut"
  | `refusal:${number}`
  | `when:${number}`;

export interface PeekShutTimingProps {
  question?: string;
  refusal?: string;
  when?: string;
  /** Frames between words as a line rises in. */
  stagger?: number;
  /** Frame the slot snaps shut; the refusal follows it. */
  shutAt?: number;
}

export const DEFAULT_QUESTION = "Want a peek?";
export const DEFAULT_REFUSAL = "That’s all you get.";
export const DEFAULT_WHEN = "The rest, Monday.";

const LINE_LEN = 18;
const Q_AT = 6;
export const STAGGER = 3;
const WORD_LEN = 14;
const OPEN_AT = 30;
const OPEN_LEN = 16;
export const SHUT_AT = 80;
const SHUT_LEN = 6;
const R_AT = 90;
const WHEN_AT = 102;
/** The "when" line waits at least this long after the refusal's last word starts. */
const WHEN_GAP = 4;
/** Frames the clip holds after the motion ends, before compression kicks in. */
const MIN_HOLD = 34;

/** A line's words, as the layout splits them. */
export function split(s: string) {
  return s.split(/\s+/).filter(Boolean);
}

// `line` draws the base line. `question:<i>` rises question word `i`, each
// following the one before. `open` opens the slot and `shut` snaps it shut;
// the picture pans from the start of `open` to the end of `shut`.
// `refusal:<i>` and `when:<i>` rise their words in two chains, the refusal
// following the shut and the "when" line following the refusal. `length`
// here is the clip after `delay`, in scene frames.
export const peekShutTimeline = defineTimeline<
  PeekShutElementId,
  PeekShutTimingProps
>(
  (
    {
      question = DEFAULT_QUESTION,
      refusal = DEFAULT_REFUSAL,
      when = DEFAULT_WHEN,
      stagger = STAGGER,
      shutAt = SHUT_AT,
    },
    { length },
  ) => {
    const qWords = split(question);
    const rWords = split(refusal);
    const wWords = split(when);
    const rAt = R_AT + (shutAt - SHUT_AT);
    const whenAt = Math.max(
      WHEN_AT + (shutAt - SHUT_AT),
      rAt + rWords.length * stagger + WHEN_GAP,
    );
    const motionEnd = whenAt + (wWords.length - 1) * stagger + WORD_LEN;
    const room = length - MIN_HOLD;
    const k = Math.max(0.6, Math.min(1, room / motionEnd));

    const words = (
      list: string[],
      at: number,
      lane: string,
      id: (i: number) => PeekShutElementId,
      lead: PeekShutElementId | undefined,
    ) =>
      list.map(
        (w, i): TimelineElement<PeekShutElementId> => ({
          id: id(i),
          lane,
          label: w,
          start: (at + i * stagger) * k,
          length: WORD_LEN * k,
          follows: i > 0 ? id(i - 1) : lead,
        }),
      );

    const elements: TimelineElement<PeekShutElementId>[] = [
      {
        id: "line",
        lane: "Slot",
        label: "line",
        start: 0,
        length: LINE_LEN * k,
      },
      ...words(qWords, Q_AT, "Question", (i) => `question:${i}`, undefined),
      {
        id: "open",
        lane: "Slot",
        label: "open",
        start: OPEN_AT * k,
        length: OPEN_LEN * k,
        follows: "line",
      },
      {
        id: "shut",
        lane: "Slot",
        label: "shut",
        start: shutAt * k,
        length: SHUT_LEN * k,
        follows: "open",
      },
      ...words(rWords, rAt, "Refusal", (i) => `refusal:${i}`, "shut"),
      ...words(
        wWords,
        whenAt,
        "When",
        (i) => `when:${i}`,
        rWords.length > 0 ? `refusal:${rWords.length - 1}` : "shut",
      ),
    ];
    return elements.sort((a, b) => a.start - b.start);
  },
);
